"""Mathematical paraphrases for previously individually assessed PAMO tasks.

This file supplies statement and topic metadata only; the regional owner keeps
all numerical ratings and holds unchanged. Source: organisers' problem archive.
"""
import json
from pathlib import Path
P=Path(__file__).resolve().parent
rows=[]
def add(y,n,t,sub,s,sol=None):
 p={'id':f'pamo_{y}_{n}','topic':t,'subtopics':sub,'statement':s,'sourceUrl':'https://www.pamoofficial.org/problems/','notes':'Statement independently paraphrased from the PAMO organisers’ archive. The numerical rating is retained from the existing individual review.'}
 if sol:p.update(solution=sol,solutionKind='original-exposition',solutionCredit='Independent mathematical exposition for Olympiad Atlas')
 rows.append(p)
add(2026,1,'Combinatorics',['Games & strategies'],r'Eight cards occupy eight consecutive positions in a row. Players alternate removing one card that still has a card in at least one of its two originally neighbouring positions. Gaps are never closed. The first player unable to move loses. Which player has a winning strategy?')
add(2026,4,'Algebra',['Polynomials','Algebraic identities'],r'Find every polynomial $P$ with nonnegative integer coefficients satisfying $P(\sqrt2)=\sqrt{P(2)}$.',r'Write $P(x)=\sum a_i x^i$. Squaring the equality yields $$\sum_i(a_i^2-a_i)2^i+2\sum_{i<j}a_i a_j2^{(i+j)/2}=0.$$ Every summand is nonnegative. Thus every coefficient is $0$ or $1$, and at most one coefficient is $1$. Conversely $P=0$ and $P(x)=x^k$ for every integer $k\ge0$ all work.')
add(2025,2,'Combinatorics',['Counting','Parity','Recurrences & generating functions'],r'Count ordered pairs of binary sequences $(x_1,\ldots,x_{20})$ and $(y_1,\ldots,y_{20})$ such that $\sum_{i=1}^{20}x_i y_i$ is even.',r'At each index three choices of $(x_i,y_i)$ contribute zero and one contributes one. Therefore the even-minus-odd count is $(3-1)^{20}=2^{20}$, while their sum is $4^{20}$. The required number is $(4^{20}+2^{20})/2$.')
add(2025,4,'Number Theory',['Divisibility & GCD','Integer polynomials'],r'Determine all integers $n$ for which $x^5-nx-(n+1)=0$ has an integer root $x$.',r'The equation is $x^5-1=n(x+1)$. The value $x=-1$ is impossible. Reduction modulo $x+1$ gives $x+1\mid2$, so $x\in\{0,1,-2,-3\}$. These yield $n\in\{-1,0,33,122\}$, respectively, and each is valid.')
add(2024,1,'Number Theory',['Primes','Diophantine equations'],r'Find all positive integer triples $(a,b,c)$ such that $$(a+b)/(a+c)=(b+c)/(a+b)$$ and $ab+bc+ca$ is prime.')
add(2000,1,'Algebra',['Trigonometry','Equations & systems'],r'Solve, on the real domain where the trigonometric expressions are defined, $$\sin^3x(1+\cot x)+\cos^3x(1+\tan x)=\cos2x.$$')
add(2000,2,'Algebra',['Polynomials','Sequences & recurrences'],r'Define $P_0(x)=x^3+213x^2-67x-2000$ and $P_n(x)=P_{n-1}(x-n)$ for $n\ge1$. What is the coefficient of $x$ in $P_{21}(x)$?',r'The successive shifts add to $1+\cdots+21=231$, so $P_{21}(x)=P_0(x-231)$. Its linear coefficient is $3\cdot231^2-426\cdot231-67=61610$.')
add(2000,4,'Algebra',['Equations & systems','Inequalities'],r'Fix real numbers $a,b,c$ with $a^2+b^2=c^2$. Find all real triples $(x,y,z)$ satisfying $$z^2=x^2+y^2,\qquad (z+c)^2=(x+a)^2+(y+b)^2.$$')
