add(2001,4,'Algebra',['Inequalities','Counting'],r'Given $n\ge1$ and real $a>0$, count the ordered real tuples $(x_1,\ldots,x_n)\in[0,a]^n$ satisfying $$\sum_{i=1}^n\bigl(x_i^2+(a-x_i)^2\bigr)=na^2.$$')
